<?php
require_once __DIR__ . '/../core/db.php'; require_once __DIR__ . '/../core/functions.php'; require_once __DIR__ . '/../core/security.php'; require_once __DIR__ . '/../core/auth.php'; require_once __DIR__ . '/../core/rbac.php'; require_once __DIR__ . '/../core/branch_portal.php';
$branchId=require_portal_branch_id(); $branch=portal_branch_row($branchId); $customCss=setting('custom_css',''); ensure_branch_price_schema();
$stmt=db()->prepare("SELECT p.name, p.category, p.base_unit, p.reorder_level, COALESCE(SUM(sl.qty_in-sl.qty_out),0) qty FROM products p LEFT JOIN stock_ledger sl ON sl.product_id=p.id AND sl.branch_id=? WHERE COALESCE(p.track_stock,1)=1 GROUP BY p.id ORDER BY p.name LIMIT 1000");
$stmt->execute([$branchId]); $rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
function navc($a){$items=['index.php'=>'Dashboard','sales.php'=>'Penjualan','shifts.php'=>'Shift','stock.php'=>'Stok']; echo '<div class="card" style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px">'; foreach($items as $u=>$l){echo '<a class="'.e($a===$u?'btn':'btn secondary').'" href="'.e(base_url('cabang/'.$u)).'">'.e($l).'</a>'; } echo '</div>';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stok Cabang</title><link rel="stylesheet" href="<?php echo e(asset_url('assets/app.css')); ?>"><style><?php echo $customCss; ?></style></head><body><div class="main" style="margin:0"><div class="content"><h2>Stok Cabang: <?php echo e($branch['branch_name'] ?? ''); ?></h2><?php navc('stock.php'); ?><div class="card"><div class="table-wrap"><table><thead><tr><th>Produk</th><th>Kategori</th><th>Qty</th><th>Min</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): $low=(float)$r['qty'] <= (float)$r['reorder_level']; ?><tr><td><?php echo e($r['name']); ?></td><td><?php echo e($r['category'] ?? '-'); ?></td><td><?php echo e(format_qty($r['qty'],$r['base_unit'])); ?></td><td><?php echo e(format_qty($r['reorder_level'],$r['base_unit'])); ?></td><td><?php echo $low?'<span style="color:#dc2626">Rendah</span>':'Aman'; ?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="5">Belum ada data stok.</td></tr><?php endif; ?></tbody></table></div></div></div></div></body></html>
